    "description": "Detrurner Leather Set je komplet za čiščenje in nego usnjenih površin. Vsebuje vse kar potrebujete za varno in učinkovito čiščenje vseh usnjenih površin.\n\nVsebina kompleta:\n1x Čistilo za usnje 250ml\n1x Premaz za usnje 250ml\n1x Krtačka za čiščenje usnja\n1x Aplikator iz mikro vlaken za nanos\n1x Mikrrpa za brisanje\n\nDeturner Leather Cleaner:\nPopolnoma varno in učinkovito sredstvo za čiščenje usnjenih površin v vozilu. Izdelek je pripravljen za uporabo in opremljen z pršilko za ustvarjenje pene, kar omogoča učinkovito čiščenje površine in zagotavlja, da se produkt ne vpije v površino. Ustvarja izjemno čisto in ne svetlečo površino. Primerno je za vse vrste usnjenih površin. Za dnevno uporabo, ga lahko redčimo z vodo v razmerju 1:1.\n\nVarnostni napotki:\nPozor: H319 Povzroča hudo draženje oči. P102 Hraniti zunaj dosega otrok. P103 – Pred uporabo preberite etiketo. P264 Po uporabi temeljito umiti roke. P305 + P351 + P338 PRI STIKU Z OČMI: previdno izpirajte z vodo nekaj minut. Odstranite kontaktne leče, če jih imate in če to lahko storite brez težav. Nadaljujte z izpiranjem. P501 Odstraniti vsebino/posodo v skladu z nacionalnimi predpisi. Sestavine po Uredbi o detergentih EC 648/2004 < 5%: anionske površinsko aktivne snovi, < 5% amfoterne površinsko aktivne snovi.\n\nDeturner Leather Protector:\nSredstvo za zaščito in obnovo vseh vrst usnjenih površin. Sredstvo povrača usnjene površine nazaj v prvotno stanje. Skrb za usnje je enako kot skrb za kožo. Formula z naravnimi sestavinami nahrani usnje in mu povrne mehkobo, obenem pa mu nudi dolgotrajno zaščito. Sredstvo usnje vlaži in s tem zmanjša možnost popokanja in sušenja. Unikatna formula je suha na otip, površina po nanosu postane gladka, vozilo pa zadiši po usnju. Zagotavlja odlično UV zaščito, ki preprečuje popokanje in bledenje usnja.\n\nVarnostni napotki:\nP102 Hraniti zunaj dosega otrok.\n\nNavodila za uporabo:\nPovršino pred čiščenjem posesajte, da odstranite vse večje delce umazanije. Nanesite čistilo direktno na ščetko ter površino dobro skrtačite. Čistite sekcijsko, nikoli čistila ne nanašajte na celo površino naenkrat. Ostanek čistila obrišite s priloženo mikro krpo ter z ravnimi gibi/brisanjem. Ko smo površino učistili nanesemo še zaščitno kremo. Pred uporabo plastenko dobro pretresite. Kremo nanesite na aplikator iz mikro vlaken ali čisto mikro krpo in jo z enakomernimi krožnimi gibi razmažite po površini. Počakajte 2 minuti in nato ostanek kreme obrišite s čisto mikro krpo. Pri starejših ali slabše ohranjenih površinah priporočamo nanos dodatnega sloja. Ni primerna za nanos na semiš.",
