    "description": "K2 Tapiflex je univerzalno brezkontaktno lepilo v spreju. Zahvaljujoč visoko kvalitetnim sestavinam je izredno učinkovit. Idealna izbira za lepljenje tekstila, pene, plastike, kovine, stekla, lesa, gume, papirja,... Odlikuje ga enostavna uporaba in hitro delovanje. Pločevinka je opremljena s posebno šobo, ki jo lahko rotiramo, tako delo postane še enostavnejše in učinkovitejše.\n\nNavodila za uporabo:\nPred uporabo površine, ki jih želimo lepiti, dobro očistimo in razmastimo. Pretresemo pločevinko (ca. 2–3 minute). Napršimo na površino iz razdalje 15–20 cm. Počakamo, da hlapi ca. 3–5 minut in površine dobro pritisnemo skupaj. Na porozne materiale nanesemo več lepila. Po uporabi pločevinko obrnemo na glavo in pritisnemo sprožilec ter tako očistimo šobo.\n\nVarnostni napotki:\nVsebuje: Ogljikovodiki, C6-C7, n-alkani, izoalkan, ciklični, <5% n-heksan. Nevarno: H222 Zelo lahko vnetljiv aerosol. H315 Povzroča draženje kože. H336 Lahko povzroči zaspanost ali omotico. H229 Posoda je pod tlakom: lahko eksplodira pri segrevanju. H412 Škodljivo za vodne organizme, z dolgotrajnimi učinki. P102 Hraniti zunaj dosega otrok. P210 Hraniti ločeno od vročine, vročih površin, isker, odprtega ognja in drugih virov vžiga. Kajenje prepovedano. P251 Ne preluknjajte ali sežigajte je niti, ko je prazna. P261 Ne vdihavati hlapov. P211 Ne pršiti proti odprtemu ognju ali drugemu viru vžiga. P271 Uporabljati le zunaj ali v dobro prezračevanem prostoru. P410 + P412 Zaščititi pred sončno svetlobo. Ne izpostavljati temperaturam nad 50°C/122 °F. P501 Odstraniti vsebino/posodo v skladu z nacionalnimi predpisi.",
