    "description": "Učinkovito sredstvo za lažji zagon tudi v najtežjih razmerah do -54 °C. Vsebuje posebne mikro delce, ki mažejo notranje dele v kritičnih razmerah. Primeren je za vse vrste motorjev in agregatov.\n\nNavodila za uporabo:\nOdpremo zaboj, kjer je zračni filter vozila in sredstvo zmerno napršimo na filter. Zapremo zaboj in zaženemo vozilo. Opozorilo: upoštevamo navodila proizvajalca vozila.\n\nVarnostni napotki:\nPred uporabo dobro preberite navodila in etiketo na plastenki. Vsebuje: dietil eter. Nevarno: H222 Zelo lahko vnetljiv aerosol. H302 Zdravju škodljivo pri zaužitju. H315 Povzroča draženje kože. H336 Lahko povzroči zaspanost ali omotico. H412 Škodljivo za vodne organizme, z dolgotrajnimi učinki. H229 Posoda je pod tlakom: lahko eksplodira pri segrevanju. EUH019 Lahko tvori eksplozivne perokside. P102 Hraniti zunaj dosega otrok. P210 Hraniti ločeno od vročine, vročih površin, isker, odprtega ognja in drugih virov vžiga. Kajenje prepovedano. P211 Ne pršiti proti odprtemu ognju ali drugemu viru vžiga. P251 Ne preluknjajte ali sežigajte je niti, ko je prazna. P264 Po uporabi temeljito umiti roke. P271 Uporabljati le zunaj ali v dobro prezračevanem prostoru. P410 + P412 Zaščititi pred sončno svetlobo. Ne izpostavljati temperaturam nad 50 °C/122 °F. P501 Odstraniti vsebino/posodo v skladu z nacionalnimi predpisi.",
