    "description": "Sredstvo na osnovi voska za dolgotrajno antikorozijsko zaščito votlih delov karoserij vozil (vrata, pragovi, boki, paneli,...). Ščiti pred vodo, soljo in rjo. Odlične sposobnosti vpijanja in izjemna obstojnost. Izredno enostaven nanos na površine. Ne odteka iz vertikalnih površin. Prozorne barve, ne škoduje barvi, laku, gumi ali plastiki.\n\nNavodila za uporabo:\nPred uporabo dobro pretresemo. Površina mora biti pred nanosom suha in čista. Nanašamo skozi obstoječe luknje na vozilu. V kolikor je potrebno, naredimo novo luknjo v velikosti cevke. Ne nanašamo na motor, zavore in izpuh.\n\nVarnostni napotki:\nVsebuje: Ogljikovodiki, C6-C7, n-alkani, izoalkani, ciklični, < 5% n-Heksan; Ogljikovodiki, C9-C12, n-alkani, izoalkani, ciklični, aromatski (2-25%). Pozor: H222 Zelo lahko vnetljiv aerosol. H315 Povzroča draženje kože. H336 Lahko povzroči zaspanost ali omotico. H372 Škoduje organom pri dolgotrajni ali ponavljajoči se izpostavljenosti. H411 Strupeno za vodne organizme, z dolgotrajnimi učinki. H229 Posoda je pod tlakom: lahko eksplodira pri segrevanju. P102 Hraniti zunaj dosega otrok. P210 Hraniti ločeno od vročine, vročih površin, isker, odprtega ognja in drugih virov vžiga. Kajenje prepovedano. P211 Ne pršiti proti odprtemu ognju ali drugemu viru vžiga. P251 Ne preluknjajte ali sežigajte je niti, ko je prazna. P260 Ne vdihavati razpršila. P271 Uporabljati le zunaj ali v dobro prezračevanem prostoru. P273 Preprečiti sproščanje v okolje. P410 + P412 Zaščititi pred sončno svetlobo. Ne izpostavljati temperaturam nad 50 °C/122 °F. P501 Odstraniti vsebino/posodo v skladu z nacionalnimi predpisi.",
